/*
 * SimpleBME280 Altimeter — read temp, pressure, calc altitude
 *
 * Wiring:
 *   VCC -> 5V
 *   GND -> GND
 *   SCL -> A5
 *   SDA -> A4
 *
 * Drag the Temp / hPa sliders on the sensor
 * to simulate different pressure conditions.
 */

#include <Wire.h>
#include <SimpleBME280.h>

SimpleBME280 bme;

#define SEALEVELPRESSURE_HPA (1013.25)

void setup() {
  Serial.begin(115200);
  Wire.begin();
  bme.begin();
  Serial.println("SimpleBME280 Altimeter");
  Serial.println("----------------------");
}

void loop() {
  float tempC   = bme.readTemperature();
  float presPa  = bme.readPressure();
  float altM    = bme.readAltitude(SEALEVELPRESSURE_HPA);

  Serial.print("Temp:      ");
  Serial.print(tempC, 1);
  Serial.println(" C");

  Serial.print("Pressure:  ");
  Serial.print(presPa / 100.0, 1);
  Serial.println(" hPa");

  Serial.print("Altitude:  ");
  Serial.print(altM, 1);
  Serial.println(" m");

  Serial.println("----------------------");
  delay(2000);
}
